    private static DocumentBlock Node(string name, Formula statement, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("majorizationtransfer-" + name.Replace('.', '-').Replace('_', '-').ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(name),
            StatementSource.FromAuthor(statement), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(prose))), role);
    private static Formula App(Formula function, params Formula[] args) => new Formula.Apply(function, [.. args]);
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
    private static Formula Op(string name) => Seq(Operatorname, Grp(F.Id(name)));
    private static Formula All(Formula name, Formula type, Formula body) =>
        Seq(Forall, Sp, Parenthesized(Seq(name, Sp, Colon, Sp, type)), Comma, Sp, body);
    private static Formula Imp(Formula hypothesis, Formula body) =>
        new Formula.Logic(Parenthesized(hypothesis), FormulaLogicOperator.Implies, Parenthesized(body));
